const app=document.querySelector('#app');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function read(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}function save(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('保存失败：请检查浏览器存储权限');return false}}function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',2600)}document.querySelector('#motion').onclick=e=>{document.body.classList.toggle('reduced');e.target.setAttribute('aria-pressed',document.body.classList.contains('reduced'))};function tile(c){return `<a class="chapter" href="#chapter/${c.章号}"><small>${esc(c.部)} / ${esc(c.惯用章名_非PDF印刷标题)}</small><img class="chapter-photo" loading="lazy" src="assets/scene-${String(c.章号).padStart(2,'0')}.webp" alt="${esc(c.界面副题_企划拟定)} · 艺术演绎"><div class="num">${String(c.章号).padStart(2,'0')}</div><h3>${esc(c.界面副题_企划拟定)}</h3><p>${esc(c.焦点与约略时间)}</p></a>`}function map(){
const progress=read('ulysses-v2-completed',[]),done=Array.isArray(progress)?progress:[];
const acts=[
{title:'海边与城中：两条清晨',from:1,to:6,text:'先随斯蒂芬离开塔楼，再从第4幕回到同日早晨，进入布卢姆的家。两个早晨并行，章号表示叙述次序。'},
{title:'城市展开：声音、工作与争执',from:7,to:12,text:'报馆、街头、图书馆与酒馆。第10幕穿插城市中的不同人，不把他们都当作布卢姆亲自经历的事。'},
{title:'入夜与归家：相遇之后',from:13,to:18,text:'从海滩到医院，再走向夜城与归途。第13幕保留格蒂的叙述位置；最后一幕进入摩莉的内心。'}
];
return `<div class="narrative-route" aria-label="按原著章节顺序排列的十八幕路线">${acts.map(act=>`<section class="route-act"><h3>${act.title}</h3><p>${act.text}</p><ol class="route-stops" start="${act.from}">${CHAPTERS.slice(act.from-1,act.to).map(c=>`<li class="route-stop ${done.includes(+c.章号)?'done':''}"><a href="game.html?chapter=${c.章号}"><b>${String(c.章号).padStart(2,'0')}</b><strong>${esc(c.界面副题_企划拟定)}</strong><small>${esc(c.焦点与约略时间)}</small><span class="status">${done.includes(+c.章号)?'已体验 · 再次进入':'进入这一幕'}</span></a></li>`).join('')}</ol></section>`).join('')}<p class="route-note">节点间距表示章节顺序，不代表时间长度或步行距离。各幕可独立进入，完成状态与全书阅读记录分别保存。</p></div>`;
}function render(){const h=location.hash.slice(1)||'home';if(h==='home'){app.innerHTML=`<section class="hero"><span class="eyebrow">A DAY IN DUBLIN / 1904</span><img class="hero-art" src="assets/dublin.webp" alt="1904年都柏林河岸艺术演绎"><h1>尤利西斯<em>一个城市，一天，<br>无数种内心。</em></h1><p class="lead">从海边的清晨，到一盏深夜的灯。<br>循着斯蒂芬、布卢姆与摩莉，<br>走进乔伊斯笔下的都柏林。</p><div class="actions"><a class="button primary" href="game.html">开始这一天 ↗</a><a class="button" href="#book">翻开全书手札</a></div><div class="ink hand">十八次看见，同一天的回声。 ↶</div></section><section class="wrap"><div class="section-top"><div><span class="eyebrow">01 / THE READING DESK</span><h2>把一天，慢慢展开。</h2></div><p class="muted">阅读与游戏各自独立。<br>你的停留，会被记住。</p></div><div class="chapter-list">${CHAPTERS.slice(0,3).map(tile).join('')}</div><p><a class="scribble" href="#book">查看十八章与序文、附录 →</a></p></section>`}else if(h==='book'){app.innerHTML=`<section class="wrap"><span class="eyebrow">THE BOOK / 三部 · 十八章</span><h2>全书手札</h2><p class="muted">荷马式英文名称是惯用导览名；章号与所用译本对应。正文与译注分别查看。</p><div class="tools"><a class="button" href="#front">序文与译者导读</a><a class="button" href="#appendix">人物表、对照与后记</a></div><div class="chapter-list">${CHAPTERS.map(tile).join('')}</div></section>`}else if(h==='map'){app.innerHTML=`<section class="wrap"><span class="eyebrow">THE NARRATIVE ATLAS</span><h2>十八幕，一天的回声。</h2><p class="muted">这是叙事关卡图，不是实际步行地图。第4幕回到同日早晨；第10幕展开并行城市；第18幕进入摩莉。</p>${map()}<div class="notice">点击任一节点进入游戏。“已体验”标示已完成的关卡；不会替你标记整章已读。</div></section>`}else if(h.startsWith('chapter/')){const c=CHAPTERS[Number(h.split('/')[1])-1];if(!c){location.hash='book';return}app.innerHTML=`<section class="wrap"><a class="back" href="#book">← 全书手札</a><p class="eyebrow">${esc(c.部)} / ${esc(c.惯用章名_非PDF印刷标题)}</p><h2>${c.章号}. ${esc(c.界面副题_企划拟定)}</h2><a href="assets/scene-${String(c.章号).padStart(2,'0')}.webp" target="_blank"><img class="chapter-photo" style="height:320px;object-fit:contain" src="assets/scene-${String(c.章号).padStart(2,'0')}.webp" alt="本章场景 · 点击看完整画幅"></a><div class="prose"><p>${esc(c.原著事件概述)}</p><div class="notice">${esc(c.交互与文体)}<br>PDF ${esc(c.PDF章全范围_含译注)} 页（含译注）；正文从第${c.start}页开始。当前为本地提取文本，尚未逐字校勘。</div><div class="reading-bar"><button id="bookmark">保存位置</button><button id="markread">标记整章已读</button><button id="fontsize">放大文字</button><a class="button primary" href="game.html?chapter=${c.章号}">体验这一幕 ↗</a><span>核对原PDF（原PDF未随项目提供）</span></div><article class="reading" id="reading" tabindex="0">${renderAtlasReading(c)}</article><p class="muted">正文依所给萧乾、文洁若译PDF本地提取；译注请在原PDF第${esc(c.译注起页_可能与正文共页)}页核对，同页交界须注意。</p><h3>继续查阅</h3><p><a class="scribble" href="#archive">地点、人物与群体档案 ↗</a></p></div></section>`;const box=document.querySelector('#reading');box.scrollTop=read('ulysses-bookmark-'+c.章号,0);document.querySelector('#bookmark').onclick=()=>{if(save('ulysses-bookmark-'+c.章号,box.scrollTop))toast('阅读位置已保存')};document.querySelector('#markread').onclick=()=>{const a=read('ulysses-read',[]);if(!a.includes(c.章号))a.push(c.章号);if(save('ulysses-read',a))toast('已标记整章已读；游戏进度独立保存')};document.querySelector('#fontsize').onclick=()=>box.style.fontSize=box.style.fontSize==='23px'?'19px':'23px'}else if(h==='gallery'){app.innerHTML=atlasGalleryHTML()}else if(h.startsWith('entry/')){app.innerHTML=atlasPage(h.split('/')[1])}else if(h.startsWith('archive')){app.innerHTML=`<section class="wrap"><span class="eyebrow">DUBLIN / PEOPLE & PLACES</span><h2>一座城，不只有街道。</h2><p class="muted">地点、人物、群体与物件的初始档案。艺术演绎、小说人物、记忆与现实资料分别辨认。</p><div class="tools"><a class="button" href="#archive/地点／空间">地点记忆</a><a class="button" href="#archive/人物">人物群像</a><a class="button" href="#archive/群体">群体</a><a class="button" href="#archive/随文小插图／物件">物件</a></div><div class="tools"><input id="search" placeholder="查找人物、地点或章节" aria-label="搜索档案"><select id="category" aria-label="筛选类型"><option value="">全部类型</option>${[...new Set(ARCHIVE.map(a=>a.类别))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div id="entries" class="archive"></div></section>`;function filter(){const q=document.querySelector('#search').value.trim(),cat=document.querySelector('#category').value;document.querySelector('#entries').innerHTML=ARCHIVE.filter(a=>(!cat||a.类别===cat)&&(!q||(a.名称+a['身份／用途说明']+a.相关章节).includes(q))).map(a=>atlasCard(a.资产ID)).join('')||'<p>没有匹配条目，请换个关键词。</p>'}document.querySelector('#search').oninput=filter;document.querySelector('#category').onchange=filter;document.querySelector('#category').value=decodeURIComponent(h.split('/').slice(1).join('/')||'');filter()}else if(h==='front'||h==='appendix'){const front=h==='front';app.innerHTML=`<section class="wrap prose"><a href="#book">← 全书</a><h2>${front?'序文与译者导读':'附录与译后记'}</h2>${(front?[['封面、制作信息',1],['目录',3],['文洁若修订本序',5],['译者序',8]]:[['附录一：人物表',1198],['附录二：荷马对照',1207],['乔伊斯大事记',1214],['译后记',1222]]).map(([s,n])=>`<p><span>${s} · PDF第${n}页 ↗（原PDF未随项目提供）</span></p>`).join('')}<p class="notice">译者与附录解释不自动等于原著中立事实。上述链接打开本项目目录中的原PDF。</p></section>`}else{app.innerHTML=`<section class="wrap prose"><span class="eyebrow">NOTES & PROVENANCE</span><h2>作品与图像来源</h2><p>《尤利西斯》作者为詹姆斯·乔伊斯；阅读资料采用萧乾、文洁若译本。页码使用所据PDF的物理页码。</p><p>小说原文、事件概述、游戏改编与编辑解释分别呈现。正文为提取文本，尚未逐字校勘。</p><p>章节场景、人物立绘与主题插图为AI艺术演绎，不是历史照片。匿名人物、书信、亡者及记忆形象采用意象表达。</p><p>参考资料：<a class="scribble" href="https://jamesjoyce.ie/work/" target="_blank" rel="noopener">James Joyce Centre ↗</a></p></section>`}window.scrollTo(0,0)}window.addEventListener('hashchange',render);render();